args<-commandArgs(TRUE);W<-normalizePath(args[1]);P<-dirname(dirname(W));q<-jsonlite::fromJSON(file.path(W,'config.json'));library(mgcv)
if(q$key!='longitudinal')quit(status=0)
out<-file.path(P,'results/plot_data');d<-read.csv(file.path(out,paste0(q$stem,'_observations.csv')));d$subject<-factor(d$subject);stopifnot(all(is.finite(d$time)),all(is.finite(d$value)),!anyDuplicated(d[c('protein','subject','visit')]))
res<-list();grids<-list();mods<-list();diag<-list();intervals<-list();warnings<-character()
for(prot in unique(d$protein)){
 z<-d[d$protein==prot,];z<-z[order(z$subject,z$time),];fit<-withCallingHandlers(gamm(value~s(time,k=10),random=list(subject=~1),data=z,method='REML',control=nlme::lmeControl(msMaxIter=200)),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')})
 g<-data.frame(time=seq(min(z$time),max(z$time),length.out=300));pr<-predict(fit$gam,g,se.fit=TRUE);g$mean<-as.numeric(pr$fit);g$se<-as.numeric(pr$se.fit);g$lower<-g$mean-1.96*g$se;g$upper<-g$mean+1.96*g$se;g$flag<-ifelse(g$lower>0,1L,ifelse(g$upper<0,-1L,0L));g$protein<-prot;grids[[prot]]<-g
 st<-summary(fit$gam)$s.table;p<-st[1,'p-value'];res[[prot]]<-data.frame(protein=prot,n_subjects=length(unique(z$subject)),n_observations=nrow(z),edf=st[1,'edf'],p_time=p)
 rr<-rle(g$flag);ends<-cumsum(rr$lengths);starts<-c(1,head(ends,-1)+1);for(i in which(rr$values!=0))intervals[[length(intervals)+1]]<-data.frame(protein=prot,start=g$time[starts[i]],end=g$time[ends[i]],direction=rr$values[i])
 z$residual<-as.numeric(residuals(fit$lme,type='normalized'));z$fitted<-as.numeric(fitted(fit$lme));pairs<-do.call(rbind,lapply(split(z,z$subject),function(a)cbind(head(a$residual,-1),tail(a$residual,-1))));lag1<-cor(pairs[,1],pairs[,2]);sens<-gamm(value~s(time,k=14),random=list(subject=~1),data=z,method='REML',control=nlme::lmeControl(msMaxIter=200));change<-max(abs(as.numeric(predict(sens$gam,g))-g$mean));qq<-qqnorm(z$residual,plot.it=FALSE);vc<-nlme::VarCorr(fit$lme)
 diag[[prot]]<-list(n_subjects=length(unique(z$subject)),n_obs=nrow(z),missing=0,edf=unname(st[1,'edf']),residual_sd=sd(z$residual),residual_QQ_correlation=cor(qq$x,qq$y),within_subject_lag1=lag1,k14_max_mean_change=change,variance_components=capture.output(print(vc)),model_converged=TRUE)
 stopifnot(all(is.finite(g$mean)),all(g$se>0),all(is.finite(coef(fit$gam))),max(abs(lag1))<.3,change<.25)
 mods[[prot]]<-list(primary=fit,sensitivity=sens,data=z)
}
s<-do.call(rbind,res);s$q_time<-p.adjust(s$p_time,'BH');write.csv(s,file.path(out,paste0(q$stem,'_statistics.csv')),row.names=FALSE);write.csv(do.call(rbind,grids),file.path(out,paste0(q$stem,'_predictions.csv')),row.names=FALSE);write.csv(do.call(rbind,intervals),file.path(out,paste0(q$stem,'_intervals.csv')),row.names=FALSE)
stopifnot(!length(warnings));saveRDS(mods,file.path(W,'fitted-models.rds'))
jsonlite::write_json(list(status='COMPUTED_REQUIRES_VISUAL_DIAGNOSTICS',method='mgcv::gamm Gaussian REML, subject random intercept; no independent GAM fallback',warnings=warnings,models=diag,p_adjustment='BH across four approximate smooth-term p-values',interval='pointwise 95% Bayesian CrI; not simultaneous coverage; local zero-exclusion flags are not multiplicity-corrected tests'),file.path(W,'statistical-diagnostics.json'),auto_unbox=TRUE,pretty=TRUE,digits=NA)
pdf(file.path(W,'model-diagnostics.pdf'),width=10,height=8);par(mfrow=c(4,2),mar=c(3,3,2,1));for(prot in names(mods)){z<-mods[[prot]]$data;plot(z$fitted,z$residual,pch=16,cex=.4,col='#668FA888',xlab='Conditional fitted',ylab='Normalized residual',main=prot);abline(h=0,lty=2);qqnorm(z$residual,pch=16,cex=.4,main=prot);qqline(z$residual,col='#D87967')};dev.off();cat('GAMM models:',nrow(s),' Subjects:',60,' Observations per protein:',s$n_observations[1],' No warnings.\n')
